import boto3

def verify_aws_mfa() -> dict:
    iam = boto3.client('iam')
    users = iam.list_users()['Users']
    non_compliant_users = []

    for user in users:
        username = user['UserName']
        mfa_devices = iam.list_mfa_devices(UserName=username)['MFADevices']
        if not mfa_devices:
            non_compliant_users.append(username)

    return {
        "compliant": len(non_compliant_users) == 0,
        "details": f"Users missing MFA: {non_compliant_users}" if non_compliant_users else "All users have MFA enabled."
    }

# Query registry for transcription configuration
$RegistryPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell\Transcription"
if (Test-Path $RegistryPath) {
    $EnableTranscripting = Get-ItemPropertyValue -Path $RegistryPath -Name "EnableTranscripting" -ErrorAction SilentlyContinue
    if ($EnableTranscripting -eq 1) {
        Write-Output "Compliant: PowerShell Transcription logging is enabled."
        exit 0
    }
}
Write-Output "Non-Compliant: PowerShell Transcription logging is disabled."
exit 1

import socket

def check_egress_filtering() -> dict:
    target_host = "detectportal.firefox.com"
    ports = [80, 443, 22, 4444]
    results = {}
    for port in ports:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(2.0)
        try:
            s.connect((target_host, port))
            results[port] = "Allowed (Potential Gap on non-web ports if 4444 open)"
            s.close()
        except socket.error:
            results[port] = "Blocked (Compliant for restricted port)"
    return {
        "compliant": results.get(4444) == "Blocked (Compliant for restricted port)",
        "details": f"Egress check details: {results}"
    }

import boto3
import json

def verify_s3_bucket_policies() -> dict:
    s3 = boto3.client('s3')
    buckets = s3.list_buckets()['Buckets']
    non_compliant = []
    for b in buckets:
        name = b['Name']
        try:
            policy = s3.get_bucket_policy(Bucket=name)
            policy_json = json.loads(policy['Policy'])
            for statement in policy_json.get('Statement', []):
                if statement.get('Effect') == 'Allow' and statement.get('Principal') == '*':
                    non_compliant.append(name)
                    break
        except Exception:
            pass
    return {
        "compliant": len(non_compliant) == 0,
        "details": f"Public buckets or wildcard principals found: {non_compliant}" if non_compliant else "All bucket policies reviewed successfully."
    }

# PowerShell audit for Windows lockout policies
$LockoutThreshold = (Get-ADDefaultDomainPasswordPolicy).LockoutThreshold
if ($LockoutThreshold -gt 0 -and $LockoutThreshold -le 5) {
    Write-Output "Compliant: Account lockout threshold is set to $LockoutThreshold (<= 5 attempts)."
    exit 0
} else {
    Write-Output "Non-Compliant: Lockout threshold is $LockoutThreshold (Recommend setting between 1 and 5)."
    exit 1
}

import dns.resolver

def verify_domain_email_security(domain: str) -> dict:
    results = {}
    try:
        spf = dns.resolver.resolve(domain, 'TXT')
        results['SPF'] = [r.to_text() for r in spf if "v=spf1" in r.to_text()]
    except Exception as e:
        results['SPF'] = f"Failed: {str(e)}"
    try:
        dmarc = dns.resolver.resolve(f'_dmarc.{domain}', 'TXT')
        results['DMARC'] = [r.to_text() for r in dmarc]
    except Exception as e:
        results['DMARC'] = f"Failed: {str(e)}"
    compliant = isinstance(results['SPF'], list) and len(results['SPF']) > 0
    return {
        "compliant": compliant,
        "details": f"Email security DNS records for {domain}: {results}"
    }

# Check for active scheduled tasks running from user temp folders
$tasks = Get-ScheduledTask | Get-ScheduledTaskInfo | Where-Object { $_.LastTaskResult -ne 0 -or $_.TaskPath -like "*Temp*" }
if ($tasks) {
    Write-Output "Alert: Found suspicious/failing scheduled tasks: $tasks"
    exit 1
} else {
    Write-Output "Compliant: No scheduled tasks running from temp paths detected."
    exit 0
}

# Verify LSASS protection in registry
$RegistryPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Lsa"
if (Test-Path $RegistryPath) {
    $RunAsPPL = Get-ItemPropertyValue -Path $RegistryPath -Name "RunAsPPL" -ErrorAction SilentlyContinue
    if ($RunAsPPL -eq 1 -or $RunAsPPL -eq 2) {
        Write-Output "Compliant: LSASS RunAsPPL Protection is active."
        exit 0
    }
}
Write-Output "Non-Compliant: LSASS RunAsPPL Protection is disabled."
exit 1

# Check SAM registry permissions (requires Admin)
$ACL = Get-Acl -Path "Registry::HKEY_LOCAL_MACHINE\SAM\SAM"
$NonSystemAccess = $ACL.Access | Where-Object { $_.IdentityReference -notmatch "SYSTEM|Administrators" }
if ($NonSystemAccess) {
    Write-Output "Non-Compliant: Non-admin users have access to SAM."
    exit 1
}
Write-Output "Compliant: SAM registry hive permissions are restricted."
exit 0

# Verify NTDS.dit file path access control list
$NtdsPath = "C:\Windows\NTDS\ntds.dit"
if (Test-Path $NtdsPath) {
    $Acl = Get-Acl $NtdsPath
    $UnsafeAccess = $Acl.Access | Where-Object { $_.IdentityReference -notmatch "SYSTEM|Domain Admins" }
    if ($UnsafeAccess) {
        Write-Output "Non-Compliant: Unprivileged users have permissions on NTDS.dit"
        exit 1
    }
}
Write-Output "Compliant: NTDS.dit access is restricted to Administrators/SYSTEM."
exit 0

# Verify Cached Logons count in Registry
$Path = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon"
if (Test-Path $Path) {
    $CachedLogons = Get-ItemPropertyValue -Path $Path -Name "CachedLogonsCount" -ErrorAction SilentlyContinue
    if ($CachedLogons -le 2) {
        Write-Output "Compliant: Cached logons count is restricted ($CachedLogons)."
        exit 0
    }
}
Write-Output "Non-Compliant: Too many cached domain logons allowed."
exit 1
